","import React, { useState } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import "./EvaluationsTable.css";

const TABLE_NAME = "x_2049102_bnb_av_0_evaluation";
const COLUMNS = "evaluation_date,star_rating,nps_score,nps_category,demand_resolved,comments";
const API_URL = `/api/now/table/${TABLE_NAME}?sysparm_display_value=all&sysparm_limit=10000&sysparm_fields=${COLUMNS}`;

function downloadFile(content: string, filename: string, mimeType: string) {
 const blob = new Blob([content], { type: mimeType });
 const url = URL.createObjectURL(blob);
 const link = document.createElement("a");
 link.href = url;
 link.download = filename;
 document.body.appendChild(link);
 link.click();
 document.body.removeChild(link);
 URL.revokeObjectURL(url);
}

function generateCSV(records: any[]): string {
 const BOM = "\uFEFF";
 const headers = ["Data da Avaliação", "Cordialidade e Presteza", "Nota NPS", "Categoria NPS", "Demanda Atendida", "Crítica ou Sugestão"];
 const rows = records.map(r => [
 r.evaluation_date?.display_value || "",
 r.star_rating?.display_value || "",
 r.nps_score?.display_value || "",
 r.nps_category?.display_value || "",
 r.demand_resolved?.display_value || "",
 `"${(r.comments?.display_value || "").replace(/"/g, '""')}"`
 ]);
 return BOM + [headers.join(";"), ...rows.map(row => row.join(";"))].join("\n");
}

function generateExcelHTML(records: any[]): string {
 const headers = ["Data da Avaliação", "Cordialidade e Presteza", "Nota NPS", "Categoria NPS", "Demanda Atendida", "Crítica ou Sugestão"];
 const headerRow = headers.map(h => `<th>${h}</th>`).join("");
 const dataRows = records.map(r =>
 `<tr>
 <td>${r.evaluation_date?.display_value || ""}</td>
 <td>${r.star_rating?.display_value || ""}</td>
 <td>${r.nps_score?.display_value || ""}</td>
 <td>${r.nps_category?.display_value || ""}</td>
 <td>${r.demand_resolved?.display_value || ""}</td>
 <td>${(r.comments?.display_value || "").replace(/</g, "&lt;")}</td>
 </tr>`
 ).join("");

 return `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">
<head><meta charset="UTF-8"></head>
<body><table border="1"><thead><tr>${headerRow}</tr></thead><tbody>${dataRows}</tbody></table></body></html>`;
}

export default function EvaluationsTable() {
 const [exporting, setExporting] = useState(false);

 const handleExport = async (format: "csv" | "excel") => {
 setExporting(true);
 try {
 const res = await fetch(API_URL, {
 headers: { Accept: "application/json", "X-UserToken": (window as any).g_ck }
 });
 const data = await res.json();
 const records = data.result || [];

 if (format === "csv") {
 const csv = generateCSV(records);
 downloadFile(csv, "avaliacoes_bnb.csv", "text/csv;charset=utf-8;");
 } else {
 const html = generateExcelHTML(records);
 downloadFile(html, "avaliacoes_bnb.xls", "application/vnd.ms-excel;charset=utf-8;");
 }
 } catch (err) {
 console.error("Export error:", err);
 } finally {
 setExporting(false);
 }
 };

 return (
 <section className="evaluations-table-section">
 <div className="evaluations-table-header">
 <h2 className="evaluations-table-title">Registros de Avaliações</h2>
 <div className="evaluations-export-buttons">
 <button
 className="export-btn export-csv"
 onClick={() => handleExport("csv")}
 disabled={exporting}
 >
 📄 Exportar CSV
 </button>
 <button
 className="export-btn export-excel"
 onClick={() => handleExport("excel")}
 disabled={exporting}
 >
 📊 Exportar Excel
 </button>
 </div>
 </div>
 <div className="evaluations-list-container">
 <NowRecordListConnected
 table={TABLE_NAME}
 columns={COLUMNS}
 hideHeader={true}
 limit={10}
 />
 </div>
 </section>
 );
}
","import React, { useState, useEffect } from "react";
import EvaluationsTable from "./EvaluationsTable";
import "./DashboardView.css";

interface Evaluation {
 star_rating: { value: string; display_value: string };
 demand_resolved: { value: string; display_value: string };
 nps_score: { value: string; display_value: string };
 nps_category: { value: string; display_value: string };
 evaluation_date: { value: string; display_value: string };
}

interface KPIData {
 totalCount: number;
 avgStarRating: number;
 pctResolved: number;
 avgNPS: number;
 promoters: number;
 neutrals: number;
 detractors: number;
 npsZone: string;
 npsScore: number;
 unresolvedCount: number;
 criticalCount: number;
}

function computeKPIs(records: Evaluation[]): KPIData {
 const total = records.length;
 if (total === 0) {
 return {
 totalCount: 0, avgStarRating: 0, pctResolved: 0, avgNPS: 0,
 promoters: 0, neutrals: 0, detractors: 0,
 npsZone: "Sem dados", npsScore: 0, unresolvedCount: 0, criticalCount: 0
 };
 }

 let starSum = 0, npsSum = 0, resolvedCount = 0;
 let promoterCount = 0, neutralCount = 0, detractorCount = 0;
 let unresolvedCount = 0, criticalCount = 0;

 records.forEach(r => {
 const star = parseInt(r.star_rating.value) || 0;
 const nps = parseInt(r.nps_score.value) || 0;
 const resolved = r.demand_resolved.value === "true" || r.demand_resolved.value === "1";

 starSum += star;
 npsSum += nps;
 if (resolved) resolvedCount++;
 else unresolvedCount++;
 if (nps >= 9) promoterCount++;
 else if (nps >= 7) neutralCount++;
 else detractorCount++;
 if (nps < 5) criticalCount++;
 });

 const pctPromoters = (promoterCount / total) * 100;
 const pctDetractors = (detractorCount / total) * 100;
 const npsScore = pctPromoters - pctDetractors;

 let npsZone = "Crítica";
 if (npsScore > 75) npsZone = "Excelente";
 else if (npsScore >= 50) npsZone = "Muito Boa";
 else if (npsScore >= 0) npsZone = "Razoável";

 return {
 totalCount: total,
 avgStarRating: starSum / total,
 pctResolved: (resolvedCount / total) * 100,
 avgNPS: npsSum / total,
 promoters: pctPromoters,
 neutrals: (neutralCount / total) * 100,
 detractors: pctDetractors,
 npsZone,
 npsScore,
 unresolvedCount,
 criticalCount
 };
}

interface Props {
 onNavigate: (view: string, title?: string) => void;
}

export default function DashboardView({ onNavigate }: Props) {
 const [kpis, setKpis] = useState<KPIData | null>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 fetch(
 "/api/now/table/x_2049102_bnb_av_0_evaluation?sysparm_display_value=all&sysparm_limit=1000",
 { headers: { Accept: "application/json", "X-UserToken": (window as any).g_ck } }
 )
 .then(res => res.json())
 .then(data => {
 setKpis(computeKPIs(data.result || []));
 setLoading(false);
 })
 .catch(() => setLoading(false));
 }, []);

 if (loading) {
 return <div className="admin-loading">Carregando dados...</div>;
 }

 if (!kpis) {
 return <div className="admin-loading">Erro ao carregar dados.</div>;
 }

 return (
 <div className="admin-dashboard">
 <header className="admin-header">
 <h1>Painel Administrativo - Avaliações BNB</h1>
 <span
 className="admin-nav-link"
 onClick={() => onNavigate("list", "Lista de Avaliações")}
 >
 Ver todas as avaliações →
 </span>
 </header>

 <section className="kpi-grid">
 <div className="kpi-card">
 <div className="kpi-label">Nota Média (Estrelas)</div>
 <div className="kpi-value star">
 {"★".repeat(Math.round(kpis.avgStarRating))}
 {"☆".repeat(5 - Math.round(kpis.avgStarRating))}
 </div>
 <div className="kpi-detail">{kpis.avgStarRating.toFixed(1)} / 5.0</div>
 </div>

 <div className="kpi-card">
 <div className="kpi-label">Demandas Resolvidas</div>
 <div className={`kpi-value ${kpis.pctResolved >= 70 ? "positive" : "critical"}`}>
 {kpis.pctResolved.toFixed(1)}%
 </div>
 <div className="kpi-detail">Sim vs Não</div>
 </div>

 <div className="kpi-card">
 <div className="kpi-label">NPS Médio</div>
 <div className={`kpi-value ${kpis.avgNPS >= 7 ? "positive" : kpis.avgNPS >= 5 ? "neutral" : "critical"}`}>
 {kpis.avgNPS.toFixed(1)}
 </div>
 <div className="kpi-detail">Escala 0-10</div>
 </div>

 <div className="kpi-card">
 <div className="kpi-label">Classificação NPS</div>
 <div className={`kpi-value ${kpis.npsScore > 50 ? "positive" : kpis.npsScore >= 0 ? "neutral" : "critical"}`}>
 {kpis.npsZone}
 </div>
 <div className="kpi-detail">
 Score: {kpis.npsScore.toFixed(0)} | P:{kpis.promoters.toFixed(0)}% N:{kpis.neutrals.toFixed(0)}% D:{kpis.detractors.toFixed(0)}%
 </div>
 </div>
 </section>

 <section className="summary-grid">
 <div className="summary-card">
 <div className="summary-icon">📊</div>
 <div className="summary-value">{kpis.totalCount}</div>
 <div className="summary-label">Total de Avaliações</div>
 </div>

 <div className="summary-card warning" onClick={() => onNavigate("list", "Demandas Não Resolvidas")}>
 <div className="summary-icon">⚠️</div>
 <div className="summary-value">{kpis.unresolvedCount}</div>
 <div className="summary-label">Demandas Não Resolvidas</div>
 </div>

 <div className="summary-card danger">
 <div className="summary-icon">🚨</div>
 <div className="summary-value">{kpis.criticalCount}</div>
 <div className="summary-label">Avaliações Críticas (NPS &lt; 5)</div>
 </div>
 </section>

 <EvaluationsTable />
 </div>
 );
}
